package com.bank.sargable.repository;

import com.bank.sargable.model.Transaction;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;
import java.time.LocalDateTime;
import java.util.List;

public interface TransactionRepository extends JpaRepository<Transaction, String> {

    // NON-SARGABLE: YEAR() on the column → index ix_created_at ignored, Seq Scan
    @Query(value = "SELECT * FROM transactions WHERE EXTRACT(YEAR FROM created_at) = :yr",
           nativeQuery = true)
    List<Transaction> byYearBad(@Param("yr") int year);

    // SARGABLE: half-open range on the raw column → Index Range Scan
    List<Transaction> findByCreatedAtGreaterThanEqualAndCreatedAtLessThan(
            LocalDateTime from, LocalDateTime to);

    // Expression index match: query uses the SAME LOWER() transformation
    @Query(value = "SELECT * FROM transactions WHERE LOWER(email) = LOWER(:email)",
           nativeQuery = true)
    List<Transaction> byEmailCaseInsensitive(@Param("email") String email);
}
