package com.bank.sargable.service;

import com.bank.sargable.model.Transaction;
import com.bank.sargable.repository.TransactionRepository;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Service;
import java.time.LocalDateTime;
import java.util.List;

@Service
public class TaxReportService {
    private static final Logger log = LoggerFactory.getLogger(TaxReportService.class);
    private final TransactionRepository repo;

    public TaxReportService(TransactionRepository repo) { this.repo = repo; }

    // The CORRECT, sargable yearly report
    public List<Transaction> yearlyReport(int year) {
        LocalDateTime from = LocalDateTime.of(year, 1, 1, 0, 0);
        LocalDateTime to   = LocalDateTime.of(year + 1, 1, 1, 0, 0);
        log.info("Sargable range: created_at >= {} AND created_at < {} (uses ix_created_at)", from, to);
        return repo.findByCreatedAtGreaterThanEqualAndCreatedAtLessThan(from, to);
    }

    public List<Transaction> byEmail(String email) {
        log.info("Case-insensitive email via expression index ix_email_lower");
        return repo.byEmailCaseInsensitive(email);
    }
}
